Definition bbyte (E : env) (id : nat) (j : Z) : Z := bv_unsigned (nth (Z.to_nat j) (eb E id) (Z_to_bv 8 0)).
Definition blen (E : env) (id : nat) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+0$id;R+1!1'2!2'3!1+4!1,5|30;!2'6#2#1").
(* [comment removed for export] *)
Definition bbody (E : env) (id : nat) (from to : Z) : list Z :=
  map (fun b : byte => bv_unsigned b) (firstn (Z.to_nat (to - from)) (skipn (Z.to_nat from) (eb E id))).
Definition bfact_ok (E : env) (bf : bfact) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S@0!1,5|600;!2'<0!2'=#8#5!2+:!2';1#1!2'>#1!2'<0!2'=#8#4|30;!3'A#:#8#3!2'C#8#6!3'A#8#6#1!2'E1#1!2'<0!2'=#9#6!2'E8#2!1,F|510;!3'A#:#8#2!1,F|519;!3'A#8#67!2'<0!2'=#6#3!2'<0!2'=#6#2$E;R+0$bf;R+7-7RN$bf;R+7w#15$id;R+1$from;R+8$to;R+8$lo;R+9$hi;R+9%j;R+9%~R2%~R!2'?!1'@#2!2'3!1+4!1,53!2'6#9#7!2+:!2';#54!2';4#4$id;R+1$from;R+8$to;R+8$lo;R+9$hi;R+9!2+B+9$j;R+9!2+:2!2+:!2'>#15!2+:!2';#36!2';6#2$id;R+1$s;R+8$ilo;R+9$ihi;R+9$f;R+1!2+B+9$i;R+9!2+:!2';,D#1!2+:!2+:!2';#4#1!2';#1#3!2+:!2'>75!2+:%j;R+9%~R!2+:!2';8#1!2'>#19!2+:!2';:;!2';;<!2+:!2+G!2'>=:!2'><=%~R!2';!2'H51!1,F|506;!2'I#3!4'J#9#789$id;R+1$es;R+8$ee;R+8$f;R+1!2+:!2+:!2';>?!2';?!2'C#6#4!2'I#1!4'J#6#4>?$id;R+1$j;R+8$v;R+9%~R!2'>!2'<0!2'=#5#2!2'C#5#3!1'K!3+L+9!3'A#6#4>#2").
Definition bfacts_ok (E : env) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$E;R+0!3+M+7!1'N#1/BR;").
Definition bfact_vars_lt (n : nat) (bf : bfact) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!2'Q#7#4!2'P0!2'Q#7#3$n;R+1$bf;R+7-7RN$bf;R+7+O#15$id;R+1$from;R+8$to;R+8$lo;R+9$hi;R+91$id;R+1$from;R+8$to;R+8$lo;R+9$hi;R+91$id;R+1$s;R+8$ilo;R+9$ihi;R+9$f;R+10$id;R+1$es;R+8$ee;R+8$f;R+1!2'P!2'Q#6#3!2'Q#6#2$id;R+1$j;R+8$v;R+9!2'Q#5#2").
Definition bfacts_vars_lt (n : nat) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$n;R+1!3'R+7!1'S#1/BR;").

