Definition lb_range (fk : list kentry) (id : nat) (rb : expr) (rk : Z) (kb : expr) (kk : Z) : Z * Z :=
  match find_bfact fk BR id rb rk kb kk with Some r => r | None => (0, 255) end.
Definition loadbyte (ss : sym_state) : option sym_state := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S<0!1+X+W!1,5|21;!1+41!2+^J22!1,5|34;!1+44!2+^J35!1,^1+W!1+T+^B!2+^J+8+9!2+^J9+1!1,_F#;$ss;R+W-XRN$x;R!1+X+a50!2'b>/IT;!1'^D#12$i;R+a5-XRN$x;R!1+X60!1'aC#12$p;R6-^JRN$p;R!2+^J350#11$p0;R3$imm;R5-^JRN$p0;R!2+^J220#21$rd;R2$rs;R2-ORN$~R+O0!3'b?1#2!3,b@1,Dvv,^4!2'bA1,D27-ORN$~R+O0!1'`T!2'bB#7!1,\+`M27&kn;R!1'_H#78&fk;R!1'bC#18&nx;R!1'^G#9+1&a;R!2'bD!2'bE!1'^E#:#4!2'bF4#6+^H&rb;R!1'`9#1+8&rk;R!1'bG#2+9-XRN$x;R!1+X:0!4'bH#5#6#2#12$p;R:-^JRN$p;R!2+^J9+10#11$p0;R9$id;R+1-^JRN$p0;R!2+^J+8+90#21$kb;R+8$kk;R+9-^JRN$x;R!2+^J+9+90!6'bI#:#3#7#6#2#11$lo;R+9$hi;R+9!2,Z+W!6,^C!2'E!1'^D#D!1,F|20;!3'bJ!1'^E#D!1'bK#?;!1,\+^F!3,^6+^B!3,_E;#2#1#=!1,_S#;!1,^1+^H777").

(* [comment removed for export] *)
Fixpoint find_bne (fk : list kentry) (brs : list bfact) (id : nat) (rb : expr) (rk : Z) (kb : expr) (kk : Z) (v : Z) : bool :=
  match brs with
  | [] => false
  | BNe id' j v' :: r =>
      if (Nat.eqb id' id && Z.eqb v' v && lin_ge0 fk [(rb, rk)] [(kb, kk); (j, 0)] && lin_ge0 fk [(kb, kk); (j, 0)] [(rb, rk)])%bool
      then true else find_bne fk r id rb rk kb kk v
  | _ :: r => find_bne fk r id rb rk kb kk v
  end.
Definition loadbyte_ne (v : Z) (ss : sym_state) : option (option sym_state * option sym_state) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "SG0!1+X+W!2+^J00!1+X1!1,5|21;!1+43!2+^J44!1,5|34;!1+46!2+^J57!1,^11!1+T+^B!2+^J+8+9!2+^J;+1!1,F,_6!2'H#E=!2'E!1'^D#D!1,F|20;!1,_F#;!3'bJ!1'^E#D!1'bK#?@!1,\+^F!1,_S#;!1,^1+^H!1,^1+W!2'E#E=$v;R+9$ss;R+W-XRN$x;R!1+X+a52!2'b>/IT;!1'^D#12$i;R+a5-XRN$x;R!1+X82!1'aC#12$p;R8-^JRN$p;R!2+^J572#11$p0;R5$imm;R7-^JRN$p0;R!2+^J442#21$rd;R4$rs;R4-ORN$~R+O2!3'b?3#2!3,b@3,Dvv,^4!2'bA3,D29-ORN$~R+O2!1'`T!2'bB#7!1,\+`M29&kn;R!1'_H#7:&fk;R!1'bC#1:&nx;R!1'^G#9+1&a;R!2'bD!2'bE!1'^E#:#4!2'bF6#6+^H&rb;R!1'`9#1+8&rk;R!1'bG#2+9-XRN$x;R!1+X<2!4'bH#5#6#2#12$p;R<-^JRN$p;R!2+^J;+12#11$p0;R;$id;R+1-^JRN$p0;R!2+^J+8+92#21$kb;R+8$kk;R+9-^JRN$x;R!2+^J+9+92!6'bI#:#3#7#6#2#11$lo;R+9$hi;R+9-ORN$~R+O2!8'bL#</BR;#5#9#8#4#3#E2!2,Z1!4,`400-ORN$~R+O0!2'_U#2>2!2,Z+W!6,^C?AB!3,^6+^B!3,_E@#2>#=CDE-ORN$~R+O0!2'_UF#12!2,Z+W!6,^C?AB!3,^6+^B!3,_E@F#1#=CDE9999").

