Lemma step_req_all : forall st, SR.step_req segs x_len ro_lo ro_hi st.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$st;R+bN-bNRN$s;R+bN!5'bO/segs;/x_len;/ro_lo;/ro_hi;#1#19$stops;R!1+T+9!1$stops;R!1+T+9vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bP#1#1vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;,bQvd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;,bR$n;R+1!1$n;R+1vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bS#1#1$n;R+1!1$n;R+1vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bT#1#1$k;R+9!1$k;R+9vd/STRLEN;!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bU#1#1$pc;R+9!1$pc;R+9vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bV#1#1$joinpc;R+9!1$joinpc;R+9vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bW#1#1$r;R+1!1$r;R+1vd,^4!5'bO/segs;/x_len;/ro_lo;/ro_hi;!1,bX#1#1").
Qed.

(* [comment removed for export] *)
Record INV2 (E : env) (ss : sym_state) (R : bvmap 5 word) (Mc : word -> option byte) : Prop := MKINV2 {
  i_regs : regs_ok E (s_regs ss) R;
  i_know : know_ok segs E Mc (s_know ss);
  i_frame : forall a : word, outside E F a -> Mc a = M0 a;
  i_grows : mem_grows M0 Mc;
  i_flat : regions_ok E F;
  i_nx : (nx0 <= s_next ss)%nat;
  i_bf : bfacts_ok E }.

