(* [comment removed for export] *)
Lemma step1_sound : forall (fx : FPState) st ss ss' E R Mc,
  step1 F st ss = Some ss' -> INV2 E ss R Mc ->
  exists (fx' : FPState) E' R' Mc',
    env_agree (s_next ss) E E' /\ (s_next ss <= s_next ss')%nat /\ INV2 E' ss' R' Mc'
