Lemma lb_range_sound : forall E Mc fk id rb rk kb kk lo hi,
  lb_range fk id rb rk kb kk = (lo, hi) ->
  Forall (kentry_ok segs E Mc) fk -> bfacts_ok E ->
  forall j, j = estart E (SA rb rk) - estart E (SA kb kk) -> 0 <= j -> j < blen E id ->
