Lemma loadbyte_sound : forall (fx : FPState) ss ss' E R Mc,
  loadbyte ss = Some ss' -> INV2 E ss R Mc ->
  exists E' R', env_agree (s_next ss) E E' /\ (s_next ss <= s_next ss')%nat /\ INV2 E' ss' R' Mc
