Lemma first_slot_index_sound : forall lo hi v ts i0 i,
  first_slot_index lo hi v ts i0 = Some i ->
  exists k, i = (i0 + k)%nat /\ (k < length ts)%nat /\ APS.is_havoc lo hi (nth k ts (ELit 0)) = Some v
